<script>(()=>{const body=document.getElementById('quotation-lines'),tpl=document.getElementById('quotation-line-template');let i=body?.querySelectorAll('tr').length||0;body?.addEventListener('change',event=>{if(!event.target.matches('[data-product]'))return;const option=event.target.selectedOptions[0],row=event.target.closest('tr');if(option.value){row.querySelector('[data-description]').value=option.dataset.name;row.querySelector('[data-unit]').value=option.dataset.unit}});document.getElementById('add-quotation-line')?.addEventListener('click',()=>{if(i>=100)return;const row=tpl.content.firstElementChild.cloneNode(true);row.querySelector('[data-product]').name=`lines[${i}][finished_good_id]`;for(const [field,name] of [['description','description'],['quantity','quantity'],['unit','unit'],['price','unit_price']])row.querySelector(`[data-${field}]`).name=`lines[${i}][${name}]`;i++;body.appendChild(row);if(window.jQuery&&jQuery.fn.select2)jQuery(row).find('select').select2({width:'100%'})})})()</script>
